import logging

from taf.alias.store import store

from .api import Helper, ScoutApi
from .config import Config
from .exceptions import InvalidPMIntervalException, UnsupportedEnvironmentException

logging.basicConfig()
logger = logging.getLogger(__name__)


class scout(object):
    """
            Introduction
            ************


            scout for easy access from robot framework to Scout API.


            Proxy settings
            **************

            If you are using HTTP proxy configured in environment variables (http_proxy, https_proxy),
            please remember to set also no_proxy variable for localhost.

            ::

                no_proxy=localhost,127.0.0.0/8


            Sample setup configurations
            ***************************

            Default - LTE (FL00)
            -----------------------------------------

            ::

            Setup scout     scout_testline_name=MRBTS-101010    environment=production


            Keywords
            ********
            """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 3

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        super(scout, self).__init__()
        self.store = store()
        self.ute_test_case_id = None

    def setup_scout(self, scout_testline_name, timeout=60, api_key=None, environment='production', alias='default', base_url=None,
                    api_version='v1'):
        """ Setup Scout API Library.

        [Important!] Locate your keywords related to taf.sw.scout in the body of your tests. Suggestion: In the
        middle of your test when Scout monitoring will connect to BTS. You should not locate taf.sw.scout keywords
        in test teardown because during the test (actions) BTS status can change and we are not able to predict the
        impact on scout monitoring. Tests with keywords in teardown will not be supported by Scout team.

        :param string scout_testline_name: name of testline registered in Scout, i.e. MRBTS-101010, CLOUD-9552
        :param int timeout: timeout for scout connection requests
        :param string api_key: Scout API Key. This is optional parameter as api_key is no longer required by most of
            keywords. If keyword requires api_key an appriopriate annotation is added to its docstring. You can request
            Your API key by email at contact provided at the top of this documentation.
        :param string environment: Scout environment name. Default is 'production'. Available: 'production',
            'staging', 'dev'. For 'dev' you have to specify base_url.
        :param string alias: Name of execution context. Default is 'default'
        :param string base_url: Custom URL of Scout instance. Required for environment='dev'. Otherwise ignored.
            Default is None.
        :param string api_version: Version of Scout API. Default is 'v1'.
        """
        alias = self._try_to_string(alias, 'alias')
        scout_testline_name = self._try_to_string(scout_testline_name, 'scout_testline_name')
        environment = self._try_to_string(environment, 'environment')

        params = {'api_key': api_key, 'base_url': base_url, 'api_version': api_version}
        api_key, base_url, api_version = self._try_to_string_multiple_values(params)

        try:
            config = Config(environment)
        except Exception:
            raise UnsupportedEnvironmentException

        if environment == 'dev' and (base_url is None or api_version is None):
            raise UnsupportedEnvironmentException('"base_url" parameter is required when environment="dev"')

        base_url = config.env_config.BASE_URL or base_url
        api_version = config.env_config.API_VERSION or api_version

        scout_api = ScoutApi(scout_testline_name=scout_testline_name, api_key=api_key, base_url=base_url,
                             api_version=api_version, config=config.config, ute_test_case_id=self.ute_test_case_id,
                             timeout=timeout)
        scout_api.setup()
        self.store.set_alias(alias, scout_api)
        self.store.set_scope(alias, 'suite')

    def _try_to_string_multiple_values(self, values_to_convert):
        return [self._try_to_string(value, item) if value else value for item, value in values_to_convert.items()]

