    def get_pm(self, pm_id, start_time, end_time, interval=None, alias='default'):
        """
        Get PM data for selected counter with given interval

        Max time range (end_time - start_time) to get data: 48h

        :param string pm_id: counter id, i.e. M8038C57
        :param string start_time: Start date from which pm should be checked. When no timezone is provided, assume local timezone.
        :param string end_time: End time to which pm should be checked. When no timezone is provided, assume local timezone.
        :param int interval: collection interval in minutes i.e. 12 (between 1-15) when BTS captures PM counter
        :param string alias: Name of execution context. Default is 'default'
        """
        alias = self._try_to_string(alias, 'alias')
        pm_id = self._try_to_string(pm_id, 'pm_id')
        interval = self._try_to_int(interval, 'interval') if interval else None
        start_time, end_time = self._process_time_range(start_time, end_time, 'pm')
        if interval is not None and interval not in range(1, 16):
            raise InvalidPMIntervalException

        return self.store.get_alias_value(alias).get_pm(pm_id, interval, start_time, end_time)

    def get_pms(self, pm_ids, start_time, end_time, interval=None, alias='default'):
        """
        Get PM data for selected counters with given interval

        Max time range (end_time - start_time) to get data: 48h

        :param list[string] pm_ids: counters ids, i.e. [M8038C57, M5000C10]
        :param string start_time: Start date from which pm should be checked. When no timezone is provided, assume local timezone.
        :param string end_time: End time to which pm should be checked. When no timezone is provided, assume local timezone.
        :param int interval: collection interval in minutes i.e. 12 (between 1-15) when BTS captures PM counter
        :param string alias: Name of execution context. Default is 'default'
        """
        alias = self._try_to_string(alias, 'alias')
        interval = self._try_to_int(interval, 'interval') if interval else None
        start_time, end_time = self._process_time_range(start_time, end_time, 'pm')
        if interval is not None and interval not in range(1, 16):
            raise InvalidPMIntervalException

        return self.store.get_alias_value(alias).get_pms(pm_ids, interval, start_time, end_time)

