    def generate_comparator_report(self, report_name, template_ids, reference_start_time, reference_end_time,
                                   current_start_time, current_end_time, reference_period_description=None,
                                   current_period_description=None, alpha_factor=0.001, block_until_ready=False,
                                   timeout=200, alias='default'):

        """
        Generate comparator report for testline based on {template_ids} templates with defined start and end date time
        ranges
        Start time and end time should be in one month range from current date.

        :param string report_name: Name of generated Comparator Report. Current date and time will be added as suffix
            to avoid Comparator Report names duplications
        :param list[int] template_ids: Ids of comparator templates to include in Report.
        :param string reference_start_time: The start date of the reference time range. When no timezone is provided, assume local timezone.
        :param string reference_end_time: The end date of the reference time range. When no timezone is provided, assume local timezone.
        :param string current_start_time: The start date of the current time range. When no timezone is provided, assume local timezone.
        :param string current_end_time: The end date of the current time range. When no timezone is provided, assume local timezone.
        :param string reference_period_description:  Field contains information about the element (in the software)
            that has been changed in the time range (previous SW version).
        :param string current_period_description: Field contains information about the element (in the software)
            that has been changed in the time range (updated SW version).
        :param float alpha_factor: The alpha index, used in the t-test calculation.
        :param string api_key: Scout API Key. You can request Your API key by email at contact provided at the top of
            this documentation.
        :param bool block_until_ready: If set to True, the method will poll the report status until it is ready.
        :param int timeout: Maximum time to wait for the report to be ready when block_until_ready is True.
        :param string alias: Name of execution context. Default is 'default'.
        """

        alias = self._try_to_string(alias, 'alias')
        report_name = self._try_to_string(report_name, 'report_name')
        template_ids = self._try_to_list(template_ids, 'template_ids')
        reference_start_time, reference_end_time = self._process_time_range(reference_start_time, reference_end_time)
        current_start_time, current_end_time = self._process_time_range(current_start_time, current_end_time)
        reference_period_description = self._try_to_string(reference_period_description, 'reference_period_description')
        current_period_description = self._try_to_string(current_period_description, 'current_period_description')
        self._check_if_bool(block_until_ready, 'block_until_ready')
        timeout = self._try_to_int(timeout, 'timeout')
        alpha_factor = self._try_to_float(alpha_factor, 'alpha_factor')

        return self.store.get_alias_value(alias).generate_comparator_report(report_name, template_ids, reference_start_time,
                                                                            reference_end_time, current_start_time,
                                                                            current_end_time, reference_period_description,
                                                                            current_period_description, alpha_factor,
                                                                            block_until_ready, timeout)

    def generate_kpi_report(self, report_name, template_id, start_time, end_time=None, alias='default'):
        """
        THIS KEYWORD REQUIRES API_KEY PROVIDED IN LIBRARY SETUP!

        Generate kpi report for testline basend on {template_id} template with defined <{start_time},{end_time}> time
        period.
        Start time and end time should be in one month range from current date.

        :param string report_name: Name for generated KPI Report. Current date and time will be added as suffix to avoid
            KPI Report names duplications
        :param string template_id: Id of template to use in KPI Report. You can find it in URL of template edit page in
            Scout.
        :param string api_key: Scout API Key. You can request Your API key by email at contact provided at the top of
            this documentation.
        :param string start_time: Start date from which kpi report should be generated. When no timezone is provided, assume local timezone.
        :param string end_time: End time to which kpi report should be generated. When no timezone is provided, assume local timezone.
        :param string alias: Name of execution context. Default is 'default'.
        """
        alias = self._try_to_string(alias, 'alias')
        template_id = self._try_to_string(template_id, 'template_id')
        start_time, end_time = self._process_time_range(start_time, end_time)

        return self.store.get_alias_value(alias).generate_kpi_report(report_name, template_id, start_time, end_time)

