    def teardown_scout_api(self, alias='default'):
        """Teardown scout api. Keyword will release used resources.

        :param string alias: Name of execution context.
        """
        alias = self._try_to_string(alias, 'alias')

        self.store.set_alias(alias, None)

    def _process_time_range(self, start_time, end_time, source=None):
        start_time = self._try_to_string(start_time, 'start_time')
        if end_time:
            end_time = self._try_to_string(end_time, 'end_time')
        start_time, end_time = Helper.parse_time_range(source, start_time, end_time)
        return start_time, end_time

    @staticmethod
    def _try_to_string(var, param_name):
        if not isinstance(var, str):
            try:
                var = str(var)
            except TypeError:
                raise TypeError('Parameter "{}" must be string'.format(param_name))
        return var

    @staticmethod
    def _try_to_int(var, param_name):
        if not isinstance(var, int):
            try:
                var = int(var)
            except TypeError:
                raise TypeError('Parameter "{}" must be integer'.format(param_name))
        return var

    @staticmethod
    def _try_to_float(var, param_name):
        if not isinstance(var, float):
            try:
                var = float(var)
            except TypeError:
                raise TypeError('Parameter "{}" must be float'.format(param_name))
        return var

    @staticmethod
    def _try_to_list(var, param_name):
        if not all(isinstance(item, (int, str)) and str(item).isdigit() for item in var):
            raise Exception('Parameter {} must be a list of integers'.format(param_name))
        return var

    @staticmethod
    def _check_if_bool(var, param_name):
        if not isinstance(var, bool):
            raise TypeError('Parameter "{}" must be integer'.format(param_name))
